import{_ as a,C as o,o as n,c as r,j as t,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/picker-runs-ci-paused.png",k=JSON.parse(`{"title":"Pause a CI test","description":"Someone who may control the project's runs pauses a CI test they watch before its next call, then resumes it or ends it, as a local run's Pause does: off by default, beside Hold a failing CI test.","frontmatter":{"title":"Pause a CI test","description":"Someone who may control the project's runs pauses a CI test they watch before its next call, then resumes it or ends it, as a local run's Pause does: off by default, beside Hold a failing CI test.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/pause-ci-test.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/pause-ci-test.html"}],["meta",{"property":"og:title","content":"Pause a CI test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Someone who may control the project's runs pauses a CI test they watch before its next call, then resumes it or ends it, as a local run's Pause does: off by default, beside Hold a failing CI test."}]]},"headers":[],"relativePath":"features/pause-ci-test.md","filePath":"features/pause-ci-test.md","lastUpdated":1795799473000}`),c={name:"features/pause-ci-test.md"};function u(p,e,w,f,g,m){const s=o("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"pause-a-ci-test",tabindex:"-1"},[i("Pause a CI test "),t("a",{class:"header-anchor",href:"#pause-a-ci-test","aria-label":'Permalink to "Pause a CI test"'},"​")],-1)),h(s,{reporter:"",fixtures:""}),e[1]||(e[1]=l('<p>A CI test that waits on an element goes past the moment worth seeing before anyone can look at it. With this setting on, a Maintainer or a Project admin who watches a CI worker in the <a href="./live-view.html">live view</a> can <strong>Pause</strong> its test before its next call, look at the page as it stands, <a href="./live-inspect.html">inspect</a> it, then <strong>Resume</strong> it or <strong>End the test</strong>: a local run&#39;s controls, on a test running in CI.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>A Project admin turns on <strong>Let controllers pause a CI test</strong> in <strong>Project → Settings → Live view</strong>. It needs <a href="./hold-ci-failure.html">Hold a failing CI test</a> on: the switch stays off until the hold is on, the API refuses it alone, and turning the hold off turns it off too. A pause lasts the <strong>Longest hold or pause</strong> at most: 1 to 15 minutes, 5 by default. It is off in every project, and needs <code>@piwitests/reporter</code> 0.75.0 or later: an older one never pauses, and its lanes offer no <strong>Pause</strong>.</p><p>The CI workers of the runs going on hear the change at once. While it is on, a CI worker follows its test&#39;s calls through Playwright&#39;s in-process instrumentation, as a local run that may pause does, so a pause stops a call before it waits for its element, where a local run&#39;s would. A test whose page was watched before the setting was turned on was followed through Playwright&#39;s own call stream, which would stop the call only after that wait: it takes no Pause, and says so; the worker&#39;s next test can pause.</p><h2 id="pause-resume-end-the-test" tabindex="-1">Pause, Resume, End the test <a class="header-anchor" href="#pause-resume-end-the-test" aria-label="Permalink to &quot;Pause, Resume, End the test&quot;">​</a></h2><p>In the run page&#39;s lane panel of a CI lane, someone with the <code>run:control</code> permission on the project (<a href="/operate/project-access.html#what-each-role-can-do">roles</a>) sees <strong>Pause</strong> while the lane&#39;s test runs. The test stops before its next call, the way a local run&#39;s <strong>Pause</strong> stops it: a test waiting in a long call stops once that call ends. Until then the lane panel says <strong>Pause asked by Ana</strong>, and <strong>Resume</strong> takes the Pause back. One Pause at a time: a second one, from anyone, is refused naming who asked the first.</p><p>The worker drops a Pause it cannot take, and the lane panel says why, with <strong>Pause</strong> offered again: no test runs (the worker is between tests, or in a <code>beforeAll</code> hook), the test&#39;s function ended first (its <code>afterEach</code> hooks and fixtures never stop, and a failure is then <a href="./hold-ci-failure.html">held</a> as any other), nobody with <code>run:control</code> watches the lane in full any more, or the setting went off.</p><p>While it is paused, the test&#39;s row and its lane panel say by whom and until when: <strong>Paused by Ana · until 12:05</strong>, or <strong>Paused · until 12:05</strong> when the instance knows no name. The lane panel shows the call the test stopped before and its place, and the live view goes on as for any watched test: the image, <a href="./live-view-layers.html">page events, text and filmstrip</a>, and <a href="./live-inspect.html">Inspect</a>. The lane panel offers:</p><ul><li><strong>Resume</strong>: the test goes on from where it stopped;</li><li><strong>End the test</strong>: the test fails there, at once, with the error <code>Ended from Piwi by Ana</code> (<code>Ended from Piwi</code> when the instance knows no name), so the CI job stays red and the test&#39;s retries run as after any failure. The call it stopped before never runs, nor does anything after it in the test or its <code>beforeEach</code> hook: the call stays held until its page closes, then fails, which the result may list as a second error. The <code>afterEach</code> hooks and fixtures tear down as after any failure. On a Playwright runner whose internals Piwi does not recognize, the test fails at its next locator call or as its function ends instead, and the call it stopped before runs first unless it is a locator call on Playwright 1.62 or later.</li></ul><p>A Viewer or a Contributor watching sees the pause, and no control. A refusal is said in the instance&#39;s words, such as &quot;The project&#39;s setting is off&quot; or &quot;You may watch this run, not control it&quot;.</p><p>The test&#39;s own timeout stops while it waits, as at a breakpoint. <strong>The CI job&#39;s own timeout still runs</strong>: the lane panel says so beside the pause. A paused test that resumes passes or fails as it would have, and its reported duration leaves the wait out.</p><h3 id="where-it-shows" tabindex="-1">Where it shows <a class="header-anchor" href="#where-it-shows" aria-label="Permalink to &quot;Where it shows&quot;">​</a></h3><p>Every surface that watches the lane shows the pause and the Pause asked in the same words: the run page&#39;s lane panel, VS Code&#39;s worker panel, the JetBrains <strong>Worker</strong> tab and the Runs window&#39;s CI run, whose test lists mark the lane <strong>Paused</strong>. The controls show on a surface whose own watch of the lane counts as a controller&#39;s, as <strong>Let it go</strong> does (<a href="./hold-ci-failure.html#where-it-shows">Where it shows</a>): an editor or Piwi Picker connected with a Maintainer&#39;s key offers them, one connected with a Viewer&#39;s key shows the pause without them. Each is asked once in each state of the lane, a refusal said in the instance&#39;s words.</p><figure><img src="'+d+'" width="488" alt="The Runs window watching worker 2 of CI run #78: the test list marks it Paused, and above its live page a box says Paused by Ana until a time, the call it stopped before, tests/checkout.spec.ts:31, The CI job’s own timeout still runs, with Resume and End the test"><figcaption>A CI test paused for you in the Runs window, with Resume and End the test.</figcaption></figure><p>The run&#39;s log says that the test is paused, and until when, in UTC:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[piwi] The test is paused at tests/checkout.spec.ts:31 for the people watching it on the run page, until 12:05:00 UTC at the latest.</span></span></code></pre></div><h2 id="when-it-ends" tabindex="-1">When it ends <a class="header-anchor" href="#when-it-ends" aria-label="Permalink to &quot;When it ends&quot;">​</a></h2><p>A pause ends at the first of:</p><ul><li><strong>Resume</strong> or <strong>End the test</strong>;</li><li>the longest pause the project set. A new length set during a pause applies to it;</li><li>nobody with <code>run:control</code> watching the lane in full any more: the last one closed the panel or moved to another lane, as for a <a href="./hold-ci-failure.html#when-it-ends">hold</a>;</li><li>the project&#39;s setting turned off, the hold&#39;s included, or the run&#39;s live view ending.</li></ul><p>A <strong>Pause</strong> that no call took yet is dropped at the same ends, and as its test&#39;s function ends: it never stops the next test. Each command is logged by the instance at info level, with the run, the worker, the command and who asked. Nothing is stored.</p><h2 id="what-it-costs-and-what-it-never-does" tabindex="-1">What it costs, and what it never does <a class="header-anchor" href="#what-it-costs-and-what-it-never-does" aria-label="Permalink to &quot;What it costs, and what it never does&quot;">​</a></h2><ul><li><strong>CI minutes.</strong> A paused test holds its CI job&#39;s runner for the longest pause at most, each time. One lane waits; the run&#39;s other workers go on.</li><li><strong>No new reach.</strong> The worker already holds its live view stream to the instance; nothing listens on the CI machine. The instance checks the settings, the permission of the person who asks and that their own watch shows that worker in full, and sends the command on that worker&#39;s stream alone; the worker takes it only on its own stream, and only while its project&#39;s setting is on.</li><li><strong>No input.</strong> The page takes no click, key or text from a viewer, and nothing is run in it. <strong>Interact</strong>, the picker acting on the page, <strong>Show the browser</strong> and <strong>Stop the run</strong> stay with local runs: cancelling a CI job belongs to CI.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./hold-ci-failure.html">Hold a failing CI test</a>: a failure waits for the people who may control the run</li><li><a href="./live-view.html">Live view of a run</a>: watching a CI run&#39;s workers</li><li><a href="./live-inspect.html">Inspect a worker&#39;s page</a>: the page at each call, with the locator picker</li><li><a href="/operate/project-access.html#what-each-role-can-do">Who can do what</a>: the <code>run:control</code> permission</li></ul>',24))])}const b=a(c,[["render",u]]);export{k as __pageData,b as default};
